import json, sys

def parse_multi_json(f):
    content = open(f).read()
    results = []
    decoder = json.JSONDecoder()
    idx = 0
    while idx < len(content):
        content_strip = content[idx:].lstrip()
        idx = len(content) - len(content_strip)
        if not content_strip:
            break
        obj, end = decoder.raw_decode(content, idx)
        results.append(obj)
        idx += end - idx
    return results

baseline = parse_multi_json('baseline-packages.json')
after = parse_multi_json('after-cpm-packages.json')

