    pkgs = {}
    for doc in data:
        for proj in doc.get('projects', []):
            pname = proj['path'].split('/')[-1]
            pkgs[pname] = {}
            for fw in proj.get('frameworks', []):
                for pkg in fw.get('topLevelPackages', []):
                    pkgs[pname][pkg['id']] = pkg.get('resolvedVersion', pkg.get('requestedVersion'))
    return pkgs

